    if (brightness < 0) {
      value = value * (1 + brightness);
    } else if (brightness > 0) {
      value = value + (255 - value) * brightness;
    }
    //value += brightness;

    if (contrast !== 0) {
      value = (value - avg) * contrast + avg;
    }
    return value + 0.5 | 0;
